  Shield,
  Users,
  CheckCircle,
  Plus,
  Save,
  ShoppingBag,
  Package,
  FileText,
  DollarSign,
  Lock,
  X,
  UserCheck,
} from 'lucide-react';

interface PermissionItem {
  id: string;
  label: string;
  enabled: boolean;
}

interface PermissionCategory {
  moduleName: string;
  icon: React.ElementType;
  items: PermissionItem[];
}

interface RoleConfig {
  id: string;
  name: string;
  description: string;
  isSystem: boolean;
  color: string;
  matrix: PermissionCategory[];
}

const DEFAULT_CATEGORIES: PermissionCategory[] = [
  {
    moduleName: 'User & Identity Management',
    icon: Users,
    items: [
      { id: 'users.view', label: 'View User Profiles', enabled: true },
      { id: 'users.create', label: 'Create New Accounts', enabled: true },
