  id: string;
  timestamp: string;
  user: string;
  action: string;
  ip: string;
  device: string;
  risk: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  status: 'ALLOWED' | 'BLOCKED' | 'FLAGGED';
}

interface ActiveSession {
  id: string;
  user: string;
  email: string;
  role: string;
  ip: string;
  location: string;
  device: string;
  loginTime: string;
}

